+            guest.create_node(1, 0x0010).unwrap();
             guest.end_frame();
         }
         // First drain yields the frame.
         assert!(ring.next_frame().unwrap().is_some());
         // Subsequent drains yield None (no empty-frame loop).
         assert!(ring.next_frame().unwrap().is_none());
