+/// count). `FILL` (-1.0), a non-positive value, or absence means auto-fit.
+pub fn grid_columns(node: &HostNode) -> Option<u32> {
+    let w = f32_prop(node, property_id::WIDTH)?;
+    if w <= 0.0 {
+        return None;
+    }
+    Some(w.round() as u32)
