         let mut guest = Guest::new(&mut mem, &layout);
         let events = guest.drain_events();
         assert_eq!(
             events,
             vec![Event::PointerUp {
                 target: 4,
                 x: 10.0,
                 y: 20.0,
                 secondary: false,
             }]
         );
