         let mut mem = tiny_mem(8);
         let (head, _) = mem.split_at_mut(crate::memory::HEADER_SIZE);
         header::set_u32(head, crate::memory::OFF_WRITE_CURSOR, 17);
         // mask = 7, so 17 & 7 = 1.
         assert_eq!(cursor(head, crate::memory::OFF_WRITE_CURSOR, 7), 1);
     }

