         let (event_slots, _arena) = rest.split_at_mut(slot_count * Opcode::SIZE);

         let op = Opcode::new(crate::category::EVENT, crate::event::POINTER_UP, 0, 5, 0, 0);
         assert!(push_event(event_slots, head, mask, &op).is_ok());
