     {
         let mut g = m.guest();
         g.begin_frame();
         g.create_node(1, pathland_core::component_type::VSTACK).unwrap();
         g.end_frame();
     }
     {
         let mut h = m.host();
         h.send_event(&pointer_up(9, 1.0, 2.0)).unwrap();
     }

