    type Item = Opcode;

    fn next(&mut self) -> Option<Opcode> {
        if self.cursor >= self.end {
            return None;
        }
        let bytes: [u8; 16] = self.slots[self.cursor..self.cursor + 16].try_into().unwrap();
        self.cursor += 16;
        Some(Opcode::from_bytes(&bytes))
    }
}

