        }
    }
    if let Some(bits) = node.properties.get(&property_id::TEXT_ALIGNMENT) {
        let a = (f32::from_bits(*bits) as u8) as u32;
        css.push_str(&format!("text-align:{};", ["left","center","right"][a.min(2) as usize]));
    }
    if let Some(bits) = node.properties.get(&property_id::TRUNCATION_MODE) {
        let t = (f32::from_bits(*bits) as u8) as u32;
        match t {
            0 => css.push_str("overflow:hidden;"),
            1 => css.push_str("text-overflow:ellipsis;overflow:hidden;"),
            _ => css.push_str("text-overflow:ellipsis;overflow:hidden;"),
