 impl Event {
     /// Encode this event as a 16-byte opcode.
     ///
     /// `TextChanged` cannot be fully encoded here — its text lives in the
     /// batch's string section — so this emits the opcode with a zero `B`
     /// offset; the batch-aware `encode_events`/`decode_events` pair in
     /// `pathland-core-transport` writes the text and its real offset.
     pub fn encode(&self) -> Opcode {
         match self {
             Event::PointerDown {
                 target,
                 x,
                 y,
                 secondary,
             } => Opcode::new(
                 category::EVENT,
                 crate::event::POINTER_DOWN,
                 flag_for(*secondary, false, false),
                 *target,
                 x.to_bits(),
                 y.to_bits(),
             ),
             Event::PointerMove {
                 target,
                 x,
                 y,
                 hovering,
                 leaving,
             } => Opcode::new(
                 category::EVENT,
                 crate::event::POINTER_MOVE,
                 flag_for(false, *hovering, *leaving),
                 *target,
                 x.to_bits(),
                 y.to_bits(),
             ),
             Event::PointerUp {
                 target,
                 x,
                 y,
                 secondary,
             } => Opcode::new(
                 category::EVENT,
                 crate::event::POINTER_UP,
                 flag_for(*secondary, false, false),
                 *target,
                 x.to_bits(),
                 y.to_bits(),
             ),
             Event::KeyDown {
                 target,
                 key_code,
                 modifiers,
                 repeat,
             } => Opcode::new(
                 category::EVENT,
                 crate::event::KEY_DOWN,
                 if *repeat { flag::KEY_REPEAT } else { 0 },
                 *target,
                 *key_code as u32,
                 *modifiers as u32,
             ),
             Event::KeyUp {
                 target,
                 key_code,
                 modifiers,
             } => Opcode::new(
                 category::EVENT,
                 crate::event::KEY_UP,
                 0,
                 *target,
                 *key_code as u32,
                 *modifiers as u32,
             ),
             Event::ValueChanged { target, value } => Opcode::new(
                 category::EVENT,
                 crate::event::VALUE_CHANGED,
                 0,
                 *target,
                 value.to_bits(),
                 0,
             ),
             Event::TextChanged { target, .. } => Opcode::new(
                 category::EVENT,
                 crate::event::TEXT_CHANGED,
                 0,
                 *target,
                 0,
                 0,
             ),
+            Event::FocusChanged { target, focused } => Opcode::new(
+                category::EVENT,
+                crate::event::FOCUS_CHANGED,
+                0,
+                *target,
+                u32::from(*focused),
+                0,
+            ),
+            Event::EditingChanged { target, editing } => Opcode::new(
+                category::EVENT,
+                crate::event::EDITING_CHANGED,
+                0,
+                *target,
+                u32::from(*editing),
+                0,
+            ),
+            Event::Submit { target } => Opcode::new(
+                category::EVENT,
+                crate::event::SUBMIT,
+                0,
+                *target,
+                0,
+                0,
+            ),
+            Event::Scroll {
+                target,
+                offset_x,
+                offset_y,
+            } => Opcode::new(
+                category::EVENT,
+                crate::event::SCROLL,
+                0,
+                *target,
+                offset_x.to_bits(),
+                offset_y.to_bits(),
+            ),
+            Event::Wheel {
+                target,
+                delta_x,
+                delta_y,
+            } => Opcode::new(
+                category::EVENT,
+                crate::event::WHEEL,
+                0,
+                *target,
+                delta_x.to_bits(),
+                delta_y.to_bits(),
+            ),
+            Event::DateChanged {
+                target,
+                days,
+                millis,
+            } => Opcode::new(
+                category::EVENT,
+                crate::event::DATE_CHANGED,
+                0,
+                *target,
+                *days as u32,
+                *millis,
