/// (-2.0) sentinels, or `None` to leave that axis to the native renderer.
/// When an alignment is provided it is emitted as the `ALIGNMENT` property.
fn frame(
    self,
    width: Option<f32>,
    height: Option<f32>,
    alignment: Option<Align>,
) -> Modified<Self, Frame> {
    self.modifier(Frame {
        width,
        height,
        alignment,
    })

