/** Shape geometry for a {@code SHAPE} node (the {@code SHAPE_KIND} enum). */
public enum ShapeKind {

    CIRCLE(0),
    RECTANGLE(1),
    ROUNDED_RECTANGLE(2),
    CAPSULE(3),
    ELLIPSE(4),
    PATH(5);

    private final int wire;

    ShapeKind(int wire) {
        this.wire = wire;
    }

    public int wire() {
        return wire;
    }
}

package com.pathland.view;

/** The visual variant of a {@code TOGGLE} control (the {@code TOGGLE_STYLE} enum). */
public enum ToggleStyle {

    SWITCH(0),
    CHECKBOX(1),
    BUTTON(2);

    private final int wire;

    ToggleStyle(int wire) {
        this.wire = wire;
    }

    public int wire() {
        return wire;
    }
}

