Now add a test to EmitterTest that verifies the new modifiers emit the correct wire value types (U8, STRING, F32 enum). Let me add a test `newModifiersEmitSpecValueTypes`:

```java
@Test
void newModifiersEmitSpecValueTypes() {
    FrameOpcodeSink sink = new FrameOpcodeSink();
    Emitter emitter = new Emitter(sink);
    View root = View.text("x")
            .hidden()
            .disabled(true)
            .fontFamily("Georgia")
            .lineLimit(2)
            .scaledToFit();
    emitter.mount(root, Environment.DEFAULT);
    Frame frame = sink.frame();

    for (Opcode op : frame.opcodes()) {
        if (op.category() == Categories.STYLE && op.command() == Commands.Style.SET_PROPERTY) {
            int property = op.b() & 0xFFFF;
            int valueType = (op.b() >>> 16) & 0xFF;
            switch (property) {
                case Properties.VISIBLE, Properties.ENABLED -> assertEquals(ValueTypes.U8, valueType);
                case Properties.LINE_LIMIT -> assertEquals(ValueTypes.U32, valueType);
                case Properties.FONT_FAMILY -> assertEquals(ValueTypes.STRING, valueType);
                case Properties.CONTENT_MODE -> assertEquals(ValueTypes.F32, valueType);
            }
        }
    }
    // VISIBLE=0 hides: U8 low byte 0; ENABLED=0 when disabled.
}
```

