  POINTER_DOWN: 0x01,
  POINTER_MOVE: 0x02,
  POINTER_UP: 0x03,
  KEY_DOWN: 0x04,
  KEY_UP: 0x05,
  VALUE_CHANGED: 0x06,
  TEXT_CHANGED: 0x07,
} as const;

export const VALUE_TYPE = {
  U8: 0x01,
  U32: 0x02,
  I32: 0x03,
  F32: 0x04,
  STRING: 0x05,
  ENUM: 0x06,
  COLOR: 0x07,
  DESIGN_TOKEN: 0x08,
} as const;

/** Component types (`u16`, low half of `B` in `TREE::CREATE_NODE`). */
export const COMPONENT = {
  HSTACK: 0x0001,
  VSTACK: 0x0002,
  TEXT: 0x0003,
  BUTTON: 0x0004,
  IMAGE: 0x0005,
