  COLOR: 0x100a,
  WIDTH: 0x100b,
  HEIGHT: 0x100c,
  OPACITY: 0x100d,
  VISIBLE: 0x100e,
  Z_INDEX: 0x100f,
  CLIPS_TO_BOUNDS: 0x1010,
  PADDING: 0x1011,
  PADDING_TOP: 0x1012,
  PADDING_RIGHT: 0x1013,
  PADDING_BOTTOM: 0x1014,
  PADDING_LEFT: 0x1015,
  BORDER_EDGES: 0x1016,
  ROLE: 0x2001,
  STATE: 0x2002,
  ENABLED: 0x2003,
  SELECTED: 0x2004,
  EVENT_LISTENERS: 0x2005,
  VALUE: 0x2006,
  MIN_VALUE: 0x2007,
  MAX_VALUE: 0x2008,
  LABEL: 0x200a,
  PROMPT: 0x200b,
} as const;

/** `EVENT_LISTENERS` bitmask bits. */
export const LISTENER = {
  POINTER_DOWN: 1 << 0,
  POINTER_MOVE: 1 << 1,
  POINTER_UP: 1 << 2,
  KEY_DOWN: 1 << 3,
  KEY_UP: 1 << 4,
} as const;

/** `BORDER_EDGES` bitmask bits. */
export const BORDER_EDGE = {
  TOP: 1 << 0,
  LEADING: 1 << 1,
  BOTTOM: 1 << 2,
  TRAILING: 1 << 3,
  ALL: 0x0f,
} as const;

/** Special `WIDTH`/`HEIGHT` size constants. */
export const SIZE = {
  FILL: -1.0,
  HUG_CONTENT: -2.0,
} as const;

/** `Alignment` wire values (protocol ENUM). */
export const ALIGNMENT = {
  LEADING: 0,
  CENTER: 1,
  TRAILING: 2,
  FILL: 3,
} as const;

/** `FontWeight` wire values (protocol ENUM). */
export const FONT_WEIGHT = {
  LIGHT: 0,
  REGULAR: 1,
  MEDIUM: 2,
  SEMIBOLD: 3,
  BOLD: 4,
} as const;

