+  /** A date picker's value changed, `B`=days since epoch, `C`=millis of day. */
+  dateChanged(target: number, days: number, millis = 0): Uint8Array {
+    return encodeBatch(
+      [new Opcode(CATEGORY.EVENT, EVENT.DATE_CHANGED, 0, target, days >>> 0, millis >>> 0)],
+      new Uint8Array(),
+      HOST_TO_GUEST,
+    );
+  },
