          [padding]="m.padding!"
          [color]="m.color!"
          [background]="m.background!"
          [border]="m.border!"
          [rounding]="m.rounding!"
          [opacity]="m.opacity!"
          [font]="m.font!"
          [frame]="m.frame!"
          [flex]="m.flex!"
          [lineLimit]="m.lineLimit!">
