          [color]="m.color!"
          [background]="m.background!"
          [border]="m.border!"
          [rounding]="m.rounding!"
          [opacity]="m.opacity!"
          [font]="m.font!"
          [frame]="m.frame!"
          [flex]="m.flex!"
          [lineLimit]="m.lineLimit!">
          @for (child of n.children(); track child) {
            <pathland-node [nodeId]="child" />
          }
        </ui-vstack>
      }
      @case ('lazyHStack') {
        <ui-hstack
          [gap]="stackGap(n)!"
          [alignment]="stackAlignment(n)!"
          [padding]="m.padding!"
          [color]="m.color!"
          [background]="m.background!"
          [border]="m.border!"
          [rounding]="m.rounding!"
          [opacity]="m.opacity!"
          [font]="m.font!"
          [frame]="m.frame!"
          [flex]="m.flex!"
          [lineLimit]="m.lineLimit!">
          @for (child of n.children(); track child) {
