/** A toggle's boolean change → `VALUE_CHANGED` (0/1). */
  onToggleInput(nodeId: number, on: boolean): void {
    this.session.sendValueChanged(nodeId, on ? 1 : 0);
  }

  /** A picker's option picked by index (segmented/radio) → `VALUE_CHANGED`. */
  onPickerIndex(nodeId: number, index: number): void {
    this.session.sendValueChanged(nodeId, index);
  }

  /** A text input's (secure field) value → `TEXT_CHANGED`. */
  onTextInput(nodeId: number, event: Event): void {
    this.session.sendTextChanged(nodeId, (event.target as HTMLInputElement).value);
  }

  /** A date picker's `YYYY-MM-DD` → `DATE_CHANGED` (preserving millis of day). */
  onDateInput(nodeId: number, event: Event): void {
    const value = (event.target as HTMLInputElement).value;
    if (!value) {
      return;
    }
    const [y, m, d] = value.split('-').map(Number);
    const days = Math.round(Date.UTC(y, m - 1, d) / 86_400_000);
    const node = this.nodeOf(nodeId);
    const millis = node?.date()?.millis ?? 0;
    this.session.sendDateChanged(nodeId, days, millis);
  }

  /** A date picker's `HH:MM` → `DATE_CHANGED` (preserving days since epoch). */
  onTimeInput(nodeId: number, event: Event): void {
    const value = (event.target as HTMLInputElement).value;
    if (!value) {
      return;
    }
    const [h, m] = value.split(':').map(Number);
    const millis = (h * 60 + m) * 60_000;
    const node = this.nodeOf(nodeId);
    const days = node?.date()?.days ?? 0;
    this.session.sendDateChanged(nodeId, days, millis);
  }

  /** Open/close a menu's item list. */
  toggleMenu(nodeId: number): void {
    this.openMenus.update((set) => {
      const next = new Set(set);
      if (next.has(nodeId)) {
        next.delete(nodeId);
      } else {
        next.add(nodeId);
      }
      return next;
    });
  }

  /** A menu item picked by index → `VALUE_CHANGED`; closes the menu. */
  selectMenuItem(nodeId: number, index: number): void {
    this.openMenus.update((set) => new Set([...set].filter((id) => id !== nodeId)));
    this.session.sendValueChanged(nodeId, index);
  }

