          [flex]="m.flex!">
          @for (child of n.children(); track child) {
            <pathland-node [nodeId]="child" />
          }
        </ui-grid>
      }
      @case ('lazyHGrid') {
        <ui-grid
          [gap]="stackGap(n)!"
          [padding]="m.padding!"
          [color]="m.color!"
          [background]="m.background!"
          [border]="m.border!"
          [rounding]="m.rounding!"
