            [rounding]="m.rounding ?? { radius: 0 }"
            [frame]="m.frame!">
          </ui-rectangle>
        } @else if (shapeKind(n) === SHAPE_KIND.CAPSULE) {
          <ui-rectangle
            [foregroundStyle]="colorFill(n)"
            [rounding]="{ radius: 999 }"
