          <ui-rectangle [foregroundStyle]="colorFill(n)" [frame]="m.frame!"></ui-rectangle>
        }
      }
      @case ('divider') {
        <pathland-not-implemented name="DIVIDER" />
      }
      @case ('progressView') {
        <pathland-not-implemented name="PROGRESS_VIEW" />
      }
      @case ('gauge') {
        <pathland-not-implemented name="GAUGE" />
      }
      @case ('stepper') {
        <pathland-not-implemented name="STEPPER" />
      }
      @case ('slider') {
        <pathland-not-implemented name="SLIDER" />
      }
      @case ('colorPicker') {
        <pathland-not-implemented name="COLOR_PICKER" />
      }
      @case ('picker') {
        @if (pickerStyle(n) === 'segmented') {
          <ui-hstack [gap]="4">
            @for (opt of pickerOptions(n); track opt.index) {
              <ui-button
                [label]="selection(n) === opt.index ? opt.label + ' ✓' : opt.label"
                (click)="onPickerIndex(n.id, opt.index)">
              </ui-button>
            }
          </ui-hstack>
        } @else if (pickerStyle(n) === 'radioGroup') {
          <ui-radio-group
            [value]="selectionString(n)"
            (valueChange)="onSelectInput(n.id, $event)">
            @for (opt of pickerOptions(n); track opt.index) {
              <div [option]="String(opt.index)">{{ opt.label }}</div>
            }
          </ui-radio-group>
        } @else if (pickerStyle(n) === 'wheel') {
          <pathland-not-implemented name="PICKER::Wheel" />
        } @else {
          <ui-select
            [value]="selectionString(n)"
            (valueChange)="onSelectInput(n.id, $event)">
            @for (opt of pickerOptions(n); track opt.index) {
              <div [option]="String(opt.index)">{{ opt.label }}</div>
            }
          </ui-select>
        }
      }
      @case ('menu') {
        <ui-hstack [gap]="0">
          <ui-button [triggerFor]="menu" [label]="menuTriggerLabel(n)"></ui-button>
          <ui-menu #menu (onSelect)="onMenuSelect(n.id, $event)">
            @for (opt of menuOptions(n); track opt.index) {
              <div [option]="String(opt.index)">{{ opt.label }}</div>
            }
          </ui-menu>
        </ui-hstack>
      }
      @case ('datePicker') {
        @if (datePickerMode(n) === 'date') {
          <ui-date-picker
            [value]="dateValue(n)"
            (valueChange)="onDatePickerInput(n.id, $event)">
          </ui-date-picker>
        } @else if (datePickerMode(n) === 'time') {
          <pathland-not-implemented name="DATE_PICKER::Time" />
        } @else {
          <pathland-not-implemented name="DATE_PICKER::DateAndTime" />
        }
      }
      @case ('image') {
        <ui-image
          [src]="imageSource(n)"
          [padding]="m.padding!"
          [color]="m.color!"
          [background]="m.background!"
          [border]="m.border!"
          [rounding]="m.rounding!"
          [opacity]="m.opacity!"
          [frame]="m.frame!"
          [flex]="m.flex!">
        </ui-image>
      }
      @default {
        @for (child of n.children(); track child) {
          <pathland-node [nodeId]="child" />
        }
      }
    }
  }
}

