/** Build a node with the given SET_PROPERTY ops applied. */
function nodeWith(component: number, props: [number, number, number][]): RetainedTree {
  const opcodes = [new Opcode(1, 1, 0, 1, component, 0)]; // TREE.CREATE_NODE
